export function getRegionalSlabRouteAccess(path, customerHost) {
  if (path === "/regional-slab-review") return !customerHost && GENERATED_REGIONAL_SLAB_PREVIEW_ENABLED ? "preview" : "not-found";
  if (!GENERATED_REGIONAL_SLAB_PAGE_BY_PATH[path]) return "not-found";
  const existingCustomerRoute = path === "/services/concrete-slabs-brisbane";
  if (customerHost) {
    if (GENERATED_REGIONAL_SLAB_PUBLISHED_ENABLED) return "public";
    return existingCustomerRoute ? "legacy" : "not-found";
  }
  if (GENERATED_REGIONAL_SLAB_PREVIEW_ENABLED) return "preview";
  return existingCustomerRoute ? "legacy" : "not-found";
}
